import { Component, h, Prop, Host } from '@stencil/core';
import classnames from 'classnames';
import type { DividerOrientation, DividerType, DividerVariant } from './types';

const prefix = 'divider';
/**
 * @slot default - Content rendered inside the horizontal divider.
 * @part base - KsDivider component shadow root element.
 * @part vertical - This is the shadow root element of the KsDivider component when type === 'vertical'.
 */
@Component({
  tag: 'ks-divider',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDivider {
  /** Determine whether the divider line is dashed. When set to `true`, the divider will display as a dashed line. */
  @Prop() dashed = false;
  /** Orientation of the divider's content. Can be one of the following values: `left`, `center`, or `right`. This applies only when the `orientation` is `horizontal` and there is content in the default slot. */
  @Prop() textAlign?: DividerOrientation;
  /** The type of the divider, determining its orientation. Can be `horizontal` or `vertical`. */
  @Prop() orientation: DividerType = 'horizontal';
  /** The variant of the divider, specifying the color scheme. Can be one of the following values: `"success"`, `"warning"`, `"error"`, `"primary"`, `"support"`, `"neutral"` or `"inverse"`. */
  @Prop() variant: DividerVariant = 'neutral';

  render() {
    const className = classnames(prefix, {
      [`${prefix}--${this.orientation}`]: this.orientation && !this.textAlign,
      [`${prefix}--orientation`]: this.textAlign,
      [`${prefix}--orientation-${this.textAlign}`]: this.textAlign,
      [`${prefix}--dashed`]: this.dashed,
    });

    if (this.orientation === 'vertical') {
      return (
        <Host class="KsDivider" ks-color={this.variant} role="separator" aria-orientation="vertical">
          <hr class={className} part="base vertical" />
        </Host>
      );
    }

    return (
      <Host class="KsDivider" ks-color={this.variant} role="separator" aria-orientation="horizontal">
        <hr class={className} part="base">
          <div class={`${prefix}__innertext`}>
            <slot></slot>
          </div>
        </hr>
      </Host>
    );
  }
}
